import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline


_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/AccumulateType.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda.h>
#include <cuda_runtime.h>
#include <algorithm>

template <typename scalar_t, typename acc_t>
__global__ void conv_transpose3d_kernel(
    const scalar_t* __restrict__ x,
    const scalar_t* __restrict__ weight,
    const scalar_t* __restrict__ bias,
    scalar_t* __restrict__ output,
    int64_t batch,
    int64_t in_channels,
    int64_t out_channels,
    int64_t in_depth,
    int64_t in_height,
    int64_t in_width,
    int64_t out_depth,
    int64_t out_height,
    int64_t out_width,
    int64_t kernel_size,
    int64_t stride,
    int64_t padding,
    int64_t groups,
    bool has_bias
) {
    constexpr int TILE_D = 2;
    constexpr int TILE_H = 8;
    constexpr int TILE_W = 8;
    constexpr int OC_TILE = 2;

    const int in_channels_i = static_cast<int>(in_channels);
    const int out_channels_i = static_cast<int>(out_channels);
    const int in_depth_i = static_cast<int>(in_depth);
    const int in_height_i = static_cast<int>(in_height);
    const int in_width_i = static_cast<int>(in_width);
    const int out_depth_i = static_cast<int>(out_depth);
    const int out_height_i = static_cast<int>(out_height);
    const int out_width_i = static_cast<int>(out_width);
    const int kernel_size_i = static_cast<int>(kernel_size);
    const int stride_i = static_cast<int>(stride);
    const int padding_i = static_cast<int>(padding);
    const int groups_i = static_cast<int>(groups);

    const int out_channels_per_group = out_channels_i / groups_i;
    const int in_channels_per_group = in_channels_i / groups_i;
    const int kernel_volume = kernel_size_i * kernel_size_i * kernel_size_i;
    const int tiles_h = (out_height_i + TILE_H - 1) / TILE_H;
    const int tiles_w = (out_width_i + TILE_W - 1) / TILE_W;

    const int tile_index = static_cast<int>(blockIdx.x);
    const int tile_d = tile_index / (tiles_h * tiles_w);
    const int tile_rem = tile_index % (tiles_h * tiles_w);
    const int tile_h = tile_rem / tiles_w;
    const int tile_w = tile_rem % tiles_w;
    const int n = static_cast<int>(blockIdx.z);

    const int oc_tiles_per_group =
        (out_channels_per_group + OC_TILE - 1) / OC_TILE;
    const int group_tile = static_cast<int>(blockIdx.y);
    const int group = group_tile / oc_tiles_per_group;
    const int oc_tile = group_tile % oc_tiles_per_group;
    const int oc_local = oc_tile * OC_TILE + (static_cast<int>(threadIdx.x) % OC_TILE);
    const bool active_oc = oc_local < out_channels_per_group;
    const int oc = group * out_channels_per_group + oc_local;

    const int od_start = tile_d * TILE_D;
    const int oh_start = tile_h * TILE_H;
    const int ow_start = tile_w * TILE_W;
    const int od_end = min(out_depth_i, od_start + TILE_D);
    const int oh_end = min(out_height_i, oh_start + TILE_H);
    const int ow_end = min(out_width_i, ow_start + TILE_W);

    const int d_num = od_start + padding_i - (kernel_size_i - 1);
    const int h_num = oh_start + padding_i - (kernel_size_i - 1);
    const int w_num = ow_start + padding_i - (kernel_size_i - 1);
    const int id_start = max(0, d_num / stride_i);
    const int ih_start = max(0, h_num / stride_i);
    const int iw_start = max(0, w_num / stride_i);

    const int id_end = min(in_depth_i, (od_end - 1 + padding_i) / stride_i + 1);
    const int ih_end = min(in_height_i, (oh_end - 1 + padding_i) / stride_i + 1);
    const int iw_end = min(in_width_i, (ow_end - 1 + padding_i) / stride_i + 1);

    const int shared_height = TILE_H + kernel_size_i - 1;
    const int shared_width = TILE_W + kernel_size_i - 1;

    extern __shared__ unsigned char shared_mem[];
    scalar_t* shared_input = reinterpret_cast<scalar_t*>(shared_mem);
    const int shared_depth_capacity = TILE_D + kernel_size_i - 1;
    const int64_t input_capacity =
        static_cast<int64_t>(shared_depth_capacity) * shared_height * shared_width;
    scalar_t* shared_weight = shared_input + input_capacity;

    const int tid = static_cast<int>(threadIdx.x);
    const int spatial_tid = tid;
    const int local_w = spatial_tid % TILE_W;
    const int local_h = (spatial_tid / TILE_W) % TILE_H;
    const int local_d = spatial_tid / (TILE_W * TILE_H);
    const int oc_local0 = oc_tile * OC_TILE;
    const int oc_local1 = oc_local0 + 1;
    const int oc0 = group * out_channels_per_group + oc_local0;
    const int oc1 = group * out_channels_per_group + oc_local1;
    const bool active_oc0 = oc_local0 < out_channels_per_group;
    const bool active_oc1 = oc_local1 < out_channels_per_group;
    const int weight_count = in_channels_per_group * OC_TILE * kernel_volume;
    for (int q = tid; q < weight_count; q += static_cast<int>(blockDim.x)) {
        int v = q;
        const int kw = v % kernel_size_i;
        v /= kernel_size_i;
        const int kh = v % kernel_size_i;
        v /= kernel_size_i;
        const int kd = v % kernel_size_i;
        v /= kernel_size_i;
        const int oc_local_weight = v % OC_TILE;
        const int ic_local_weight = v / OC_TILE;
        scalar_t value = scalar_t(0);
        const int oc_group = oc_tile * OC_TILE + oc_local_weight;
        if (oc_group < out_channels_per_group) {
            const int weight_ic = group * in_channels_per_group + ic_local_weight;
            const int64_t weight_offset =
                (static_cast<int64_t>(weight_ic) * out_channels_per_group + oc_group) *
                    kernel_volume +
                (kd * kernel_size_i + kh) * kernel_size_i + kw;
            value = weight[weight_offset];
        }
        shared_weight[q] = value;
    }
    __syncthreads();
    acc_t sum0 = (has_bias && active_oc0) ?
        static_cast<acc_t>(bias[oc0]) : acc_t(0);
    acc_t sum1 = (has_bias && active_oc1) ?
        static_cast<acc_t>(bias[oc1]) : acc_t(0);
    for (int ic_local = 0; ic_local < in_channels_per_group; ++ic_local) {
        const int ic = group * in_channels_per_group + ic_local;
        const int shared_depth = max(0, id_end - id_start);
        const int shared_h = max(0, ih_end - ih_start);
        const int shared_w = max(0, iw_end - iw_start);
        const int shared_count = shared_depth * shared_h * shared_w;
        for (int q = tid; q < shared_count; q += static_cast<int>(blockDim.x)) {
            int v = q;
            const int iw = v % shared_w;
            v /= shared_w;
            const int ih = v % shared_h;
            v /= shared_h;
            const int id = v;
            const int input_d = id_start + id;
            const int input_h = ih_start + ih;
            const int input_w = iw_start + iw;
            const int64_t x_offset =
                (((static_cast<int64_t>(n) * in_channels_i + ic) * in_depth_i + input_d) *
                     in_height_i + input_h) *
                    in_width_i + input_w;
            const int64_t smem_offset =
                (static_cast<int64_t>(id) * shared_height + ih) * shared_width + iw;
            shared_input[smem_offset] = x[x_offset];
        }
        __syncthreads();
        const int od = od_start + local_d;
        const int oh = oh_start + local_h;
        const int ow = ow_start + local_w;
        if ((active_oc0 || active_oc1) &&
            od < out_depth_i && oh < out_height_i && ow < out_width_i) {
            for (int kd = 0; kd < kernel_size_i; ++kd) {
                const int td = od + padding_i - kd;
                if (td < 0 || td % stride_i != 0) continue;
                const int id = td / stride_i;
                if (id >= in_depth_i || id < id_start || id >= id_end) continue;
                for (int kh = 0; kh < kernel_size_i; ++kh) {
                    const int th = oh + padding_i - kh;
                    if (th < 0 || th % stride_i != 0) continue;
                    const int ih = th / stride_i;
                    if (ih >= in_height_i || ih < ih_start || ih >= ih_end) continue;
                    for (int kw = 0; kw < kernel_size_i; ++kw) {
                        const int tw = ow + padding_i - kw;
                        if (tw < 0 || tw % stride_i != 0) continue;
                        const int iw = tw / stride_i;
                        if (iw >= in_width_i || iw < iw_start || iw >= iw_end) continue;
                        const int kernel_offset =
                            (kd * kernel_size_i + kh) * kernel_size_i + kw;
                        const int64_t smem_offset =
                            (static_cast<int64_t>(id - id_start) * shared_height +
                             (ih - ih_start)) *
                                shared_width +
                            (iw - iw_start);
                        const int weight_base = ic_local * OC_TILE * kernel_volume +
                                                 kernel_offset;
                        const acc_t input_value =
                            static_cast<acc_t>(shared_input[smem_offset]);
                        if (active_oc0) {
                            sum0 += input_value * static_cast<acc_t>(
                                shared_weight[weight_base]);
                        }
                        if (active_oc1) {
                            sum1 += input_value * static_cast<acc_t>(
                                shared_weight[weight_base + kernel_volume]);
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    const int od = od_start + local_d;
    const int oh = oh_start + local_h;
    const int ow = ow_start + local_w;
    if (od < out_depth_i && oh < out_height_i && ow < out_width_i) {
        if (active_oc0) {
            const int64_t output_offset =
                (((static_cast<int64_t>(n) * out_channels_i + oc0) *
                      out_depth_i + od) *
                     out_height_i + oh) *
                    out_width_i + ow;
            output[output_offset] = static_cast<scalar_t>(sum0);
        }
        if (active_oc1) {
            const int64_t output_offset =
                (((static_cast<int64_t>(n) * out_channels_i + oc1) *
                      out_depth_i + od) *
                     out_height_i + oh) *
                    out_width_i + ow;
            output[output_offset] = static_cast<scalar_t>(sum1);
        }
    }

}  // closes conv_transpose3d_kernel
template <typename scalar_t>
at::Tensor conv_transpose3d_cuda_impl(
    const at::Tensor& x,
    const at::Tensor& weight,
    const c10::optional<at::Tensor>& bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups
) {
    const auto batch = x.size(0);
    const auto in_channels = x.size(1);
    const auto in_depth = x.size(2);
    const auto in_height = x.size(3);
    const auto in_width = x.size(4);

    const auto kernel_size = weight.size(2);
    const auto out_channels_per_group = weight.size(1);
    const auto out_channels = out_channels_per_group * groups;

    const auto out_depth =
        (in_depth - 1) * stride - 2 * padding + kernel_size + output_padding;
    const auto out_height =
        (in_height - 1) * stride - 2 * padding + kernel_size + output_padding;
    const auto out_width =
        (in_width - 1) * stride - 2 * padding + kernel_size + output_padding;

    auto output = at::empty(
        {batch, out_channels, out_depth, out_height, out_width},
        x.options());

    const int64_t tiles_d = (out_depth + 2 - 1) / 2;
    const int64_t tiles_h = (out_height + 8 - 1) / 8;
    const int64_t tiles_w = (out_width + 8 - 1) / 8;
    const int64_t tile_count = tiles_d * tiles_h * tiles_w;
    const int64_t oc_tiles_per_group =
        (out_channels_per_group + 2 - 1) / 2;
    const int64_t channel_tile_count = groups * oc_tiles_per_group;
    const scalar_t* bias_ptr = nullptr;
    bool has_bias = false;
    if (bias.has_value() && bias->defined()) {
        bias_ptr = bias->data_ptr<scalar_t>();
        has_bias = true;
    }
    constexpr int threads = 128;
    const dim3 blocks(
        static_cast<unsigned int>(tile_count),
        static_cast<unsigned int>(channel_tile_count),
        static_cast<unsigned int>(batch));
    const int64_t input_smem_elements =
        (2 + kernel_size - 1) *
        (8 + kernel_size - 1) *
        (8 + kernel_size - 1);
    const int64_t in_channels_per_group = in_channels / groups;
    const int64_t kernel_volume =
        kernel_size * kernel_size * kernel_size;
    const int64_t weight_smem_elements =
        (in_channels_per_group * 2 * kernel_volume);
    const size_t smem_bytes = static_cast<size_t>(
        input_smem_elements + weight_smem_elements) * sizeof(scalar_t);

    auto stream = at::cuda::getCurrentCUDAStream();
    using acc_t = at::acc_type<scalar_t, true>;

    conv_transpose3d_kernel<scalar_t, acc_t>
        <<<blocks, threads, smem_bytes, stream>>>(
            x.data_ptr<scalar_t>(),
            weight.data_ptr<scalar_t>(),
            bias_ptr,
            output.data_ptr<scalar_t>(),
            batch,
            in_channels,
            out_channels,
            in_depth,
            in_height,
            in_width,
            out_depth,
            out_height,
            out_width,
            kernel_size,
            stride,
            padding,
            groups,
            has_bias);

    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return output;
}

at::Tensor conv_transpose3d_cuda(
    const at::Tensor& x,
    const at::Tensor& weight,
    const c10::optional<at::Tensor>& bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups
) {
    TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
    TORCH_CHECK(weight.is_cuda(), "weight must be a CUDA tensor");
    TORCH_CHECK(x.dim() == 5, "x must be 5-dimensional");
    TORCH_CHECK(weight.dim() == 5, "weight must be 5-dimensional");
    TORCH_CHECK(stride > 0, "stride must be positive");
    TORCH_CHECK(padding >= 0, "padding must be non-negative");
    TORCH_CHECK(output_padding >= 0, "output_padding must be non-negative");
    TORCH_CHECK(groups > 0, "groups must be positive");
    TORCH_CHECK(x.size(1) % groups == 0, "input channels must be divisible by groups");
    TORCH_CHECK(weight.size(0) == x.size(1),
                "weight input-channel dimension mismatch");
    TORCH_CHECK(weight.size(2) == weight.size(3) &&
                    weight.size(3) == weight.size(4),
                "only square kernels are supported");
    TORCH_CHECK(output_padding < stride,
                "output_padding must be smaller than stride");

    if (bias.has_value() && bias->defined()) {
        TORCH_CHECK(bias->is_cuda(), "bias must be a CUDA tensor");
        TORCH_CHECK(bias->numel() == weight.size(1) * groups,
                    "bias dimension mismatch");
    }

    auto x_contig = x.contiguous();
    auto weight_contig = weight.contiguous();

    c10::optional<at::Tensor> bias_contig = c10::nullopt;
    if (bias.has_value() && bias->defined()) {
        bias_contig = bias->contiguous();
    }
    TORCH_CHECK(
        weight_contig.scalar_type() == x_contig.scalar_type(),
        "x and weight must have the same dtype");
    if (bias_contig.has_value()) {
        TORCH_CHECK(
            bias_contig->scalar_type() == x_contig.scalar_type(),
            "x and bias must have the same dtype");
    }


    at::Tensor result;
    AT_DISPATCH_FLOATING_TYPES_AND_HALF(
        x_contig.scalar_type(),
        "conv_transpose3d_cuda",
        [&] {
            result = conv_transpose3d_cuda_impl<scalar_t>(
                x_contig,
                weight_contig,
                bias_contig,
                stride,
                padding,
                output_padding,
                groups);
        });

    return result;
}
"""

_cpp_src = r"""
#include <torch/extension.h>
at::Tensor conv_transpose3d_cuda(
    const at::Tensor& x,
    const at::Tensor& weight,
    const c10::optional<at::Tensor>& bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups
);
at::Tensor conv_transpose3d(
    const at::Tensor& x,
    const at::Tensor& weight,
    const c10::optional<at::Tensor>& bias,
    int64_t stride,
    int64_t padding,
    int64_t output_padding,
    int64_t groups
) {
    return conv_transpose3d_cuda(
        x, weight, bias, stride, padding, output_padding, groups);
}
"""

_conv_transpose3d_ext = load_inline(
    name="custom_conv_transpose3d_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["conv_transpose3d"],
    extra_cuda_cflags=["-O3"],
    extra_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(
        self,
        in_channels: int,
        out_channels: int,
        kernel_size: int,
        stride: int = 1,
        padding: int = 0,
        output_padding: int = 0,
        groups: int = 1,
        bias: bool = False,
    ):
        super().__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels,
            out_channels,
            kernel_size=(kernel_size, kernel_size, kernel_size),
            stride=stride,
            padding=padding,
            output_padding=output_padding,
            groups=groups,
            bias=bias,
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return _conv_transpose3d_ext.conv_transpose3d(
            x,
            self.conv_transpose3d.weight,
            self.conv_transpose3d.bias,
            self.conv_transpose3d.stride[0],
            self.conv_transpose3d.padding[0],
            self.conv_transpose3d.output_padding[0],
            self.conv_transpose3d.groups,
        )

